        min: Optional['types.BeneficiaryMinAggregateInput'] = None,
        max: Optional['types.BeneficiaryMaxAggregateInput'] = None,
        having: Optional['types.BeneficiaryScalarWhereWithAggregatesInput'] = None,
        count: Optional[Union[bool, 'types.BeneficiaryCountAggregateInput']] = None,
        order: Optional[Union[Mapping['types.BeneficiaryScalarFieldKeys', 'types.SortOrder'], List[Mapping['types.BeneficiaryScalarFieldKeys', 'types.SortOrder']]]] = None,
